/**
 * Agent-authored calibration scene for the isolated crane experiment.
 * It is NOT generated by Gemini and NEVER bundled as a production preset.
 * Three problems and observable solutions in one continuous SceneProgram world.
 */
export const craneExperimentSentences = [
  'Você carrega sacos de cimento até a obra, mas o peso faz você parar.',
  'Então instala uma roldana; a carga sobe, mas puxar a corda continua difícil.',
  'Você monta um guincho com motor e engrenagens, e os sacos chegam ao alto.',
];
export const craneExperimentScript = craneExperimentSentences.join(' ');
export const craneExperimentSources = craneExperimentSentences.map((text, i) => ({
  sourceId: 's' + (i + 1), text, duration: [6, 6, 8][i]!,
}));

type V = [number, number, number];
type Key = { sourceId: string; phase: number; value: V };
const k = (sourceId: string, phase: number, value: V): Key => ({ sourceId, phase, value });
const nodes: Record<string, unknown>[] = [];
const tracks: Record<string, unknown>[] = [];
const checks: Record<string, unknown>[] = [];
const add = (id: string, kind: 'mesh' | 'group' | 'actor', position: V, options: Record<string, unknown> = {}) => {
  nodes.push({ id, kind, contextSourceId: 's1', position, ...options });
};
const box = (id: string, position: V, size: V, color: string, extra: Record<string, unknown> = {}) =>
  add(id, 'mesh', position, { geometry: { shape: 'box', size }, color, ...extra });
const cyl = (id: string, position: V, size: V, color: string, extra: Record<string, unknown> = {}) =>
  add(id, 'mesh', position, { geometry: { shape: 'cylinder', size }, color, ...extra });
const curve = (node: string, channel: string, keys: Key[], interpolation = 'smooth') =>
  tracks.push({ node, channel, interpolation, keys });
const check = (sourceId: string, node: string, channel: string, kind: string, startPhase: number, endPhase: number, threshold: number) =>
  checks.push({ sourceId, node, channel, kind, startPhase, endPhase, threshold });

export function craneExperimentProgram() {
  // Populate inside the function; no global array accumulates across tests.
  nodes.length = 0; tracks.length = 0; checks.length = 0;

  // Bright construction environment and visible worksite depth.
  box('ground', [0, -.13, 0], [36, .26, 36], '#6FAE76');
  box('concrete-road', [-1, -.005, 1.6], [7, .025, 2.6], '#AEB4AC');
  box('building', [5.8, 3.3, -4.5], [6.4, 6.6, 3.6], '#F3DEB5');
  box('building-face', [5.8, 3.3, -2.63], [6.4, 6.6, .11], '#DD976A');
  for (let f = 0; f < 4; f++) {
    box('floor-' + f, [5.8, 1.2 + f * 1.45, -1.95], [7.2, .22, 4.8], '#EBD5C1');
    for (let col = 0; col < 3; col++)
      box('window-' + f + '-' + col, [3.75 + col * 2.0, 1.85 + f * 1.40, -2.55],
        [.88, .85, .075], '#74BED9');
  }
  for (const [i, x] of [2.55, 9.05].entries()) {
    cyl('scaffold-' + i, [x, 3.7, -.75], [.08, .08, 7.4], '#477184');
  }
  box('top-scaffold', [5.8, 7.43, -.75], [7.4, .12, .22], '#F1C349');

  // A worker that moves and staggers, rather than being a stationary presenter.
  add('worker', 'actor', [-3.1, 0, 1.5], { color: '#F07E42' });
  cyl('helmet-top', [0, .23, -.02], [.36, .38, .15], '#FFC833', { parent: 'worker', socket: 'head' });
  box('cement-bag-carried', [.07, -.16, .08], [.55, .72, .32], '#E9E1C9',
    { parent: 'worker', socket: 'rightHand', geometry: { shape: 'box', size: [.55, .72, .32], bevel: .07, bevelSegments: 3 } });
  curve('worker', 'position', [
    k('s1', 0, [-3.1, 0, 1.5]), k('s1', .28, [-2.82, 0, 1.5]),
    k('s1', .65, [-2.03, 0, 1.5]), k('s1', 1, [-2.03, 0, 1.5]),
  ], 'linear');
  // Feet and arms are now solved by the SceneProgram motor from worker travel.
  // The director no longer supplies absolute foot waypoints for ordinary walks.
  curve('worker', 'bodyRotation', [
    k('s1', 0, [0, 0, .04]), k('s1', .6, [0, 0, .08]),
    k('s1', .79, [.25, 0, -.24]), k('s1', 1, [.12, 0, -.1]),
    k('s2', .38, [.12, 0, -.15]), k('s2', .72, [.22, 0, -.05]),
    k('s3', 1, [0, 0, 0]),
  ]);
  curve('worker', 'face', [
    k('s1', 0, [0, 0, .15]), k('s1', .75, [-.8, 0, .8]),
    k('s2', 1, [-.7, 0, .8]), k('s3', .9, [.6, 0, .3]),
  ]);

  // Cargo is one persistent object throughout all three attempts.
  add('load', 'group', [0, .45, .1]);
  box('cement-bag-1', [-.35, 0, 0], [.62, .45, .65], '#EEE2BB', { parent: 'load' });
  box('cement-bag-2', [.33, 0, 0], [.62, .45, .65], '#E0D5B0', { parent: 'load' });
  box('cement-bag-3', [0, .41, 0], [.65, .42, .62], '#F7E7C6', { parent: 'load' });
  box('load-net', [0, -.1, 0], [1.55, .10, 1.05], '#C08B51', { parent: 'load' });
  curve('load', 'position', [
    k('s1', 0, [0, .45, .1]), k('s1', 1, [0, .45, .1]),
    k('s2', .26, [0, .45, .1]), k('s2', .87, [0, 1.78, .1]),
    k('s3', .24, [0, 1.78, .1]), k('s3', .92, [0, 5.35, .1]),
    k('s3', 1, [0, 5.35, .1]),
  ]);

  // Reusable pulley mechanism. It is assembled visibly in the second beat.
  add('pulley-install', 'group', [0, 6.15, .1]);
  add('pulley-rotor', 'group', [0, 0, 0], { parent: 'pulley-install' });
  add('pulley-rim', 'mesh', [0, 0, 0], { parent: 'pulley-rotor',
    color: '#F2BB38', geometry: { shape: 'torus', size: [.47, .09] } });
  cyl('pulley-axle', [0, 0, 0], [.13, .13, .28], '#34495F',
    { parent: 'pulley-install', rotation: [Math.PI / 2, 0, 0] });
  box('pulley-spoke-a', [0, 0, 0], [.75, .10, .11], '#26445A', { parent: 'pulley-rotor' });
  box('pulley-spoke-b', [0, 0, 0], [.10, .75, .11], '#26445A', { parent: 'pulley-rotor' });
  box('pulley-hook', [0, .72, 0], [.20, .68, .18], '#D7DBE1', { parent: 'pulley-install' });
  curve('pulley-install', 'scale', [
    k('s1', 0, [.01, .01, .01]), k('s1', 1, [.01, .01, .01]),
    k('s2', .12, [.01, .01, .01]), k('s2', .30, [1, 1, 1]),
    k('s3', 1, [1, 1, 1]),
  ]);
  curve('pulley-rotor', 'rotation', [
    k('s1', 0, [0, 0, 0]), k('s2', .30, [0, 0, 0]),
    k('s2', 1, [0, 0, -4.8]), k('s3', 1, [0, 0, -18]),
  ], 'linear');

  // The rope visibly shortens while attached to the rising load.
  box('rope', [0, 3.27, .1], [.047, 1, .047], '#FFF4DD');
  curve('rope', 'scale', [
    k('s1', 0, [.01, .01, .01]), k('s1', 1, [.01, .01, .01]),
    k('s2', .18, [1, .01, 1]), k('s2', .30, [1, 5.5, 1]),
    k('s2', .87, [1, 4.17, 1]), k('s3', .24, [1, 4.17, 1]),
    k('s3', .92, [1, .60, 1]), k('s3', 1, [1, .60, 1]),
  ]);
  curve('rope', 'position', [
    k('s1', 0, [0, 3.27, .1]), k('s2', .30, [0, 3.27, .1]),
    k('s2', .87, [0, 3.94, .1]), k('s3', .24, [0, 3.94, .1]),
    k('s3', .92, [0, 5.72, .1]), k('s3', 1, [0, 5.72, .1]),
  ]);

  // A third-beat motor, spool and toothed gear become visible through assembly.
  add('winch-install', 'group', [-2.95, .86, -.3]);
  box('winch-stand', [0, -.58, 0], [2.45, .18, 1.25], '#315873', { parent: 'winch-install' });
  cyl('motor-body', [-.52, 0, 0], [.43, .46, .92], '#4A89A9', { parent: 'winch-install',
    rotation: [0, 0, Math.PI / 2] });
  add('gear-rotor', 'group', [.46, .1, .45], { parent: 'winch-install' });
  add('gear-ring', 'mesh', [0, 0, 0], { parent: 'gear-rotor',
    color: '#FFC643', geometry: { shape: 'torus', size: [.47, .17] } });
  for (let i = 0; i < 10; i++) {
    const a = i * Math.PI / 5;
    box('gear-tooth-' + i, [.61 * Math.cos(a), .61 * Math.sin(a), 0],
      [.22, .21, .16], '#F2B132', { parent: 'gear-rotor', rotation: [0, 0, a] });
  }
  add('drum-rotor', 'group', [1.07, -.05, 0], { parent: 'winch-install' });
  cyl('drum-core', [0, 0, 0], [.28, .28, .85], '#8499A5',
    { parent: 'drum-rotor', rotation: [Math.PI / 2, 0, 0] });
  cyl('drum-flange', [0, 0, .5], [.43, .43, .08], '#E9B84D',
    { parent: 'drum-rotor', rotation: [Math.PI / 2, 0, 0] });
  box('motor-switch', [-1, .38, .55], [.32, .18, .16], '#E65A4A', { parent: 'winch-install' });
  curve('winch-install', 'scale', [
    k('s1', 0, [.01, .01, .01]), k('s2', 1, [.01, .01, .01]),
    k('s3', .05, [.01, .01, .01]), k('s3', .23, [1, 1, 1]), k('s3', 1, [1, 1, 1]),
  ]);
  curve('gear-rotor', 'rotation', [
    k('s1', 0, [0, 0, 0]), k('s3', .24, [0, 0, 0]), k('s3', 1, [0, 0, 16.0]),
  ], 'linear');
  curve('drum-rotor', 'rotation', [
    k('s1', 0, [0, 0, 0]), k('s3', .24, [0, 0, 0]), k('s3', 1, [0, 0, 10.0]),
  ], 'linear');

  check('s1', 'worker', 'position', 'change', .02, .65, .9);
  check('s2', 'load', 'position', 'change', .30, .90, .9);
  check('s2', 'pulley-rotor', 'rotation', 'change', .32, .95, 2.5);
  check('s3', 'winch-install', 'scale', 'change', .04, .25, 1.0);
  check('s3', 'gear-rotor', 'rotation', 'change', .25, .95, 8.0);
  check('s3', 'load', 'position', 'change', .25, .95, 2.2);

  return {
    version: 1,
    background: '#74B9EE',
    nodes: structuredClone(nodes),
    tracks: structuredClone(tracks),
    shots: [
      // Steady three-quarter angles: the worker/physics move, not the camera.
      { sourceId: 's1', subjects: ['worker', 'load'], azimuth: .16, endAzimuth: .16, elevation: .12, distance: 1.04 },
      { sourceId: 's2', subjects: ['load', 'pulley-install'], azimuth: .24, endAzimuth: .24, elevation: .16, distance: 1.04 },
      { sourceId: 's3', subjects: ['winch-install', 'load', 'pulley-install'], azimuth: .22, endAzimuth: .22, elevation: .16, distance: 1.04 },
    ],
    contacts: [],
    motionChecks: structuredClone(checks),
  };
}

export function craneExperimentFixture() {
  return {
    id: 'grua-tres-etapas',
    script: craneExperimentScript,
    duration: 20,
    response: {
      title: 'Grua: esforço, roldana e guincho — calibração 3D',
      scenes: craneExperimentSources.map((s) => ({
        sourceId: s.sourceId, visual: 'character', mood: 'neutral', palette: 'teal',
      })),
      sceneProgram: craneExperimentProgram(),
    },
  };
}
